// banc-fly-page-qa-20261108.js — QA of the autonomous fly ON THE REAL PAGE (fly-brain.html on localhost, through window.__flyTest).
// The page's CSP (script-src 'self', connect-src 'self') refuses a harness loaded from elsewhere and any direct call to the fork, so:
//   PASTE this whole file into the page's console (or a DevTools snippet) on http://127.0.0.1:<port>/fly-brain.html, then
//   await QA.runLogic();   // stubbed endpoints and a fake wallet: nothing leaves the page
//   await QA.runFork();    // the money loop through the page's own server, which must run in test mode on a LOCAL FORK (TB_RPC_TEST)
// The fly wallet is funded on the fork from node (banc-fly-qa-20261108.mjs --fund <address>), never by this page. Nothing may touch mainnet.

window.QA = (() => {
const T = () => window.__flyTest;
const $ = (id) => document.getElementById(id);
const sleep = (ms) => new Promise((o) => setTimeout(o, ms));
const notes = () => [...$('autoLog').children].map((p) => p.textContent);
const json = (b, status = 200) => new Response(JSON.stringify(b), { status, headers: { 'content-type': 'application/json' } });
const word = (a) => String(a).slice(2).toLowerCase().padStart(64, '0');
const ROUTER = '0x9ee35bf1bd69a03c6f0393582030fce8bb93d418', USDC = '0x833589fcd6edb6e08f4c7c32d4f71b54bda02913';

/* fetch stubs: [regex, (url, init) => body | Response]; everything else goes to the real server */
function stubFetch(handlers, calls = []) {
  const real = window.__realFetch || (window.__realFetch = window.fetch.bind(window));
  window.fetch = async (u, init) => {
    const url = String(u);
    for (const [re, fn] of handlers) if (re.test(url)) { calls.push(url); const b = await fn(url, init); return b instanceof Response ? b : json(b); }
    return real(u, init);
  };
  return calls;
}
function unstub() { if (window.__realFetch) window.fetch = window.__realFetch; }
let keccak = null;
const hashOf = async (raw) => { keccak = keccak || (await import('/keccak.js')); const h = raw.slice(2); return keccak.keccak256Hex(Uint8Array.from(h.match(/../g), (x) => parseInt(x, 16))); };
/* the money endpoints of the fly, stubbed: an account, a gas estimate, a relay that answers the right hash, a mined receipt */
function moneyStubs({ account, plan, relay, estimate } = {}) {
  return [
    [/\/api\/fly\/account\//, (u) => ({ ok: true, address: T().auto.s.address, nonce: '0', baseFeePerGas: '1000000', block: 1, eth: '1000000000000000', usdc: '5000000', stock: u.includes('token=') ? '0' : null, ...(account ? account(u) : {}) })],
    [/\/api\/fly\/estimate/, () => (estimate ? estimate() : { ok: true, gas: '60000' })],
    [/\/api\/fly\/relay/, async (u, init) => (relay ? relay(JSON.parse(init.body)) : { ok: true, hash: await hashOf(JSON.parse(init.body).raw) })],
    [/\/api\/fly\/receipt\//, () => ({ ok: true, receipt: { status: '0x1', blockNumber: '0x1', gasUsed: '0x5208' } })],
    [/\/api\/rails\/plan/, (u) => (plan ? plan(new URL(u, location.href).searchParams) : { ok: false, etat: 'NON_MESURE', pourquoi: 'stub' })],
  ];
}
/* a fresh fly wallet, set straight into the page's state (key generated by the page's own fly-wallet.js) */
async function freshWallet({ running = true, owner = '0x' + '5'.repeat(40) } = {}) {
  const W = await import('/fly-wallet.js'), key = W.newKeyHex();
  T().auto.s = { v: 1, key, address: W.addressOf(key), owner, running, day: '', today: 0, traded: [], created: Date.now(), consentAt: Date.now() };
  localStorage.setItem('fly-auto-wallet-v1', JSON.stringify(T().auto.s));
  /* the page re-renders its buttons on a storage event (another tab): a disabled button ignores click() */
  window.dispatchEvent(new StorageEvent('storage', { key: 'fly-auto-wallet-v1' }));
  $('autoLog').textContent = ''; return T().auto.s;
}
const decision = (word, extra = {}) => ({ type: 'decision', sim: false, word, action: 'x', t: word === 'approach' ? 0.1 : word === 'avoid' ? -0.1 : 0, threshold: 0.02,
  mix: { received: 100, sent: 0, moved: 0 }, ap: 1, av: 1, ...extra });
/* a swap the browser guard accepts: a known router, naming only the fly */
const swapCall = (fly) => ({ to: ROUTER, data: '0x12345678' + word(fly), value: '0x0', nom: 'swap (stub)' });

const results = [];
/* 09/11: a BUY happens only when the fly's edge pays the fee (fly-core.edgePaysFee): with no record it buys nothing. A scenario that needs a
 *   buy gives it an EARNED record (300 right / 100 wrong) on a 0.4% usual move: expected 0.19% a window > 0.05% pool + 0.10% interface */
const EARNED = { consistent: 300, opposite: 100, flat: 0, undecided: 0 };
/* the pool fee is READ from the live price windows (null right after load or after a session reset): an earned record waits for it, as
 *   the rule refuses to buy while the fee is unknown */
const earned = async () => { for (let k = 0; k < 120 && T().session.feePips == null; k++) await sleep(500);
  T().session.restore({ ...T().session.state(), tally: { ...EARNED }, typical: 0.004 }); return T().session.feePips; };
const check = (name, ok, detail) => { results.push({ name, ok: !!ok, detail }); console.log((ok ? 'ok  ' : 'KO  ') + name + ' — ' + detail); return ok; };

/* ── LOGIC: every scenario on stubbed endpoints ── */
async function runLogic() {
  results.length = 0;
  $('autoProven').checked = true; $('autoDay').value = '10'; $('autoCap').value = '0.5';

  /* 1. the record gate must not trap a position: a SELL is a way OUT of risk */
  { await freshWallet(); T().session.restore({});
    const calls = stubFetch(moneyStubs({ account: (u) => ({ stock: u.includes('token=') ? '123456789' : null }) }));
    await T().autoTrade(decision('avoid'));
    const n = notes().join(' | ');
    check('record gate lets a SELL out', calls.some((u) => u.includes('/api/rails/plan')) && !/does not beat a coin flip/.test(n), n.slice(0, 160));
    await freshWallet(); stubFetch(moneyStubs());
    await T().autoTrade(decision('approach'));
    check('record gate still holds a BUY', /does not beat a coin flip/.test(notes().join(' | ')), notes()[0].slice(0, 120)); }

  /* 2. the fly's own log is bounded: a long run must not grow the page without end */
  { await freshWallet(); stubFetch(moneyStubs());
    for (let k = 0; k < 400; k++) await T().autoTrade(decision('undecided'));
    check('the fly log is bounded over 400 decisions', $('autoLog').children.length <= 200, $('autoLog').children.length + ' lines kept'); }

  /* 3. approvals that never end in a swap are not a trade */
  { await freshWallet(); $('autoProven').checked = false; await earned();
    const fly = T().auto.s.address;
    stubFetch(moneyStubs({ plan: (q) => ({ ok: true, etat: 'APPROBATIONS', resume: { paye: q.get('montant'), fraisBps: 10 }, aSigner: [{ to: USDC, data: '0x095ea7b3' + word(ROUTER) + BigInt(q.get('montant')).toString(16).padStart(64, '0'), value: '0x0', nom: 'approve (stub)' }] }) }));
    await T().autoTrade(decision('approach'));
    const st = JSON.parse(localStorage.getItem('fly-auto-wallet-v1'));
    /* game313: the day's slot is RESERVED before sending (a reload mid-trade must not lift the cap), so it stays counted: today = 1, but no
     *   trade is reported done and the note says nothing was traded */
    check('approvals without a swap are not reported as a trade (the reserved slot stays counted)', st.today === 1 && !notes().some((x) => /done on its own/.test(x)) && /nothing traded/.test(notes()[0]), 'today=' + st.today + ' · ' + notes()[0].slice(0, 120));
    void fly; }

  /* 4. a stock switched while a trade is in flight: the seal is the memory that DECIDED, under its own stock */
  { await freshWallet(); $('autoProven').checked = false; await earned();
    const first = T().current(), fly = T().auto.s.address, F = await import('/fly-seal.js');
    localStorage.removeItem('fly-seal-v1-' + first.symbol); /* a seal left by an earlier run of this page would be read as this one */
    const decided = Array(T().fly.exportMemory().length).fill(50000); T().fly.importMemory(decided);
    let switched = false;
    stubFetch(moneyStubs({ plan: (q) => ({ ok: true, etat: 'PRET', resume: { paye: q.get('montant'), fraisBps: 10 }, aSigner: [swapCall(fly)] }),
      relay: async (b) => { if (!switched) { switched = true; $('pick').value = '1'; $('pick').dispatchEvent(new Event('change')); } return { ok: true, hash: await hashOf(b.raw) }; } }));
    await T().autoTrade(decision('approach'));
    const seal = JSON.parse(localStorage.getItem('fly-seal-v1-' + first.symbol) || 'null');
    check('a seal made after a stock switch is the memory that decided', !seal || seal.fingerprint === F.memoryFingerprint(decided),
      seal ? 'sealed ' + seal.fingerprint.slice(0, 12) + ' vs decided ' + F.memoryFingerprint(decided).slice(0, 12) : 'not sealed: ' + notes().slice(0, 2).join(' | ').slice(0, 140));
    $('pick').value = '0'; $('pick').dispatchEvent(new Event('change')); await sleep(300); }

  /* 5. Fund pressed twice while the first funding is in flight: ONE funding */
  { await freshWallet({ running: false, owner: null }); $('autoRisk').checked = true; $('autoBudget').value = '1';
    const sent = []; window.ethereum = { request: async ({ method, params }) => {
      if (method === 'eth_requestAccounts') return ['0x' + '7'.repeat(40)];
      if (method === 'eth_chainId') return '0x2105';
      if (method === 'wallet_sendCalls') throw Object.assign(new Error('Method not supported'), { code: -32601 });
      if (method === 'eth_sendTransaction') { sent.push(params[0]); await sleep(800); return '0x' + String(sent.length).padStart(64, '0'); }
      if (method === 'eth_getTransactionReceipt') return { status: '0x1' };
      throw new Error('fake wallet: ' + method); } };
    stubFetch(moneyStubs({ account: () => ({ usdc: '0', eth: '0' }) }));
    $('autoFund').click(); await sleep(50); $('autoFund').click();
    for (let k = 0; k < 60 && !/Funded|Not funded/.test($('autoState').textContent); k++) await sleep(200);
    await sleep(2500);
    check('Fund pressed twice sends one funding', sent.length === 2, sent.length + ' wallet transactions (USDC + gas = 2 expected)'); }

  /* 6. Withdraw pressed twice: one withdraw; Start and Fund are off while it runs */
  { await freshWallet({ running: true }); window.confirm = () => true;
    const calls = stubFetch(moneyStubs({ account: () => ({ usdc: '0', eth: '0', stock: '0' }) }));
    const w1 = T().autoWithdraw(); await sleep(300); const w2 = T().autoWithdraw(); await sleep(300);
    const startOff = $('autoStart').disabled, fundOff = $('autoFund').disabled;
    await sleep(4500); const reads = calls.filter((u) => u.includes('/api/fly/account/')).length;
    check('Withdraw twice runs ONE withdraw, Start/Fund off meanwhile', reads <= 4 && startOff && fundOff, reads + ' balance reads in 5 s (one loop: 3), Start ' + (startOff ? 'off' : 'ON') + ', Fund ' + (fundOff ? 'off' : 'ON'));
    await Promise.all([w1, w2]); }

  /* 7. a memory saved an hour ago: its smells still waiting for lessons are NOT taught by today's moves */
  { unstub(); const sym = T().current().symbol, key = 'fly-brain-memory-v1-' + sym;
    const st = { ...T().session.state(), recent: [{ received: 500, sent: 0, moved: 0 }, null, null], lastOdor: { received: 500, sent: 0, moved: 0 } };
    localStorage.setItem(key, JSON.stringify({ m: T().fly.exportMemory(), ...st, at: Date.now() - 3600000 }));
    $('pick').value = '1'; $('pick').dispatchEvent(new Event('change')); $('pick').value = '0'; $('pick').dispatchEvent(new Event('change'));
    const old = T().session.next();
    localStorage.setItem(key, JSON.stringify({ m: T().fly.exportMemory(), ...st, at: Date.now() - 5000 }));
    $('pick').value = '1'; $('pick').dispatchEvent(new Event('change')); $('pick').value = '0'; $('pick').dispatchEvent(new Event('change'));
    const fresh = T().session.next();
    check('a smell saved an hour ago is not taught by today\'s move; one saved 5 s ago is', old && old.lessons.length === 0 && fresh && fresh.lessons.length === 1,
      'lessons after a 1 h old save: ' + (old && old.lessons.length) + ', after a 5 s old save: ' + (fresh && fresh.lessons.length)); }

  /* 8. ripples (one per real trade) stay bounded even when no frame is drawn (hidden tab) */
  { const S = T().session, sym = T().current().symbol, P = { priceUsd: 100, tokenDecimals: 8, feePips: 500, block: 1 };
    const tx = (k) => ({ tx: '0x' + (0xabc000000 + k).toString(16).padStart(64, '0'), bloc: k, signataire: '0x' + 'a'.repeat(40), mouvements: [{ de: '0x' + 'b'.repeat(40), vers: '0x' + 'a'.repeat(40), montant: '100000000' }] });
    S.reset(); S.window({ symbol: sym, price: P, transactions: [] });
    for (let w = 1; w <= 5; w++) S.window({ symbol: sym, price: P, transactions: Array.from({ length: 100 }, (_, k) => tx(w * 1000 + k)) });
    check('ripples bounded after 500 trades in 5 windows', T().ripples() <= 200, T().ripples() + ' ripples held');
    T().fly.drain(); $('pick').value = '1'; $('pick').dispatchEvent(new Event('change')); $('pick').value = '0'; $('pick').dispatchEvent(new Event('change')); }

  /* 9. a wallet that batches: Fund pressed again 1 s after the batch went out (not mined yet) sends nothing more */
  { await freshWallet({ running: false, owner: null }); $('autoRisk').checked = true; $('autoBudget').value = '1';
    const batches = []; let minedAt = Infinity;
    window.ethereum = { request: async ({ method, params }) => {
      if (method === 'eth_requestAccounts') return ['0x' + '7'.repeat(40)];
      if (method === 'eth_chainId') return '0x2105';
      if (method === 'wallet_sendCalls') { batches.push(params[0]); minedAt = Date.now() + 4000; return { id: '0xbatch' + batches.length }; }
      throw new Error('fake wallet: ' + method); } };
    stubFetch(moneyStubs({ account: () => (Date.now() >= minedAt ? { usdc: '1000000', eth: '200000000000000' } : { usdc: '0', eth: '0' }) }));
    $('autoFund').click(); await sleep(1000); $('autoFund').click(); await sleep(1500); $('autoFund').click();
    for (let k = 0; k < 50 && !/Funded|Not funded/.test($('autoState').textContent); k++) await sleep(200);
    await sleep(300); $('autoFund').click(); await sleep(1500);
    check('a batched funding is not sent twice while it is being mined', batches.length === 1, batches.length + ' batches sent; then: ' + $('autoState').textContent.slice(0, 80)); }

  /* 10. a node that does not answer the gas estimate is not called a refusal by the chain */
  { await freshWallet(); $('autoProven').checked = false; await earned(); const fly = T().auto.s.address;
    stubFetch(moneyStubs({ plan: (q) => ({ ok: true, etat: 'PRET', resume: { paye: q.get('montant'), fraisBps: 10 }, aSigner: [swapCall(fly)] }), estimate: () => ({ ok: false, why: '429 Too Many Requests' }) }));
    await T().autoTrade(decision('approach'));
    const all = notes().join(' | ');
    check('a node error is said as a node error, not as the chain refusing', !/chain refuses/.test(all) && /not answered/.test(all), all.slice(0, 160));
    stubFetch(moneyStubs({ plan: (q) => ({ ok: true, etat: 'PRET', resume: { paye: q.get('montant'), fraisBps: 10 }, aSigner: [swapCall(T().auto.s.address)] }), estimate: () => ({ ok: false, refused: true, why: 'execution reverted' }) }));
    await freshWallet(); await T().autoTrade(decision('approach'));
    check('a revert is still said as the chain refusing', /chain refuses/.test(notes().join(' | ')), notes()[0].slice(0, 120)); }

  /* 11. switching stock while holding: what it still holds of the stock left is said */
  { await freshWallet({ running: true }); const left = T().current();
    stubFetch(moneyStubs({ account: (u) => ({ stock: u.includes(left.address) ? '250000000' : '0' }) }));
    $('pick').value = '1'; $('pick').dispatchEvent(new Event('change')); await sleep(1500);
    check('switching stock while holding says what it still holds', notes().some((x) => x.includes('still holds') && x.includes(left.symbol)), (notes()[0] || 'no note').slice(0, 140));
    unstub(); $('pick').value = '0'; $('pick').dispatchEvent(new Event('change')); await sleep(300); }

  /* 12. edge: no record -> no buy, nothing planned; an earned record whose edge pays the fee -> the planned amount IS min(USDC, cap) */
  { await freshWallet(); $('autoProven').checked = false; T().session.restore({ ...T().session.state(), tally: { consistent: 0, opposite: 0, flat: 0, undecided: 0 }, typical: 0.0015 });
    const calls = stubFetch(moneyStubs());
    await T().autoTrade(decision('approach'));
    check('no record: its edge does not pay the fee, nothing planned', !calls.some((u) => u.includes('/api/rails/plan')) && /does not pay the fee yet: .* no buy/.test(notes()[0]), notes()[0].slice(0, 200));
    await freshWallet(); await earned(); const asked = [];
    stubFetch(moneyStubs({ plan: (q) => { asked.push(q.get('montant')); return { ok: false, etat: 'NON_MESURE', pourquoi: 'stub' }; } }));
    await T().autoTrade(decision('approach'));
    check('an earned record whose edge pays the fee: min(USDC, cap) is planned', asked[0] === '500000', 'planned ' + asked[0] + ' (cap 0.5 USDC, fee read: ' + T().session.feePips + ')'); }

  /* 13. a route whose interface fee is higher (0.5%): the edge that paid on Aerodrome (0.19% vs 0.15%) does not pay it, nothing is signed */
  { await freshWallet(); $('autoProven').checked = false; await earned(); const fly = T().auto.s.address, relayed = [];
    stubFetch(moneyStubs({ plan: (q) => ({ ok: true, etat: 'PRET', resume: { paye: q.get('montant'), fraisBps: 50 }, aSigner: [swapCall(fly)] }), relay: async (b) => { relayed.push(b); return { ok: true, hash: await hashOf(b.raw) }; } }));
    await T().autoTrade(decision('approach'));
    check('a route costing more than its edge: nothing signed', relayed.length === 0 && /this route costs 0\.50% interface .* nothing signed/.test(notes()[0]), relayed.length + ' relayed · ' + notes()[0].slice(0, 180)); }

  unstub(); delete window.ethereum; await freshWallet({ running: false, owner: null }); localStorage.removeItem('fly-auto-wallet-v1'); T().auto.s = null;
  const ko = results.filter((r) => !r.ok).length;
  console.log(results.length + ' scenarios, ' + ko + ' KO');
  return { n: results.length, ko, results };
}

/* ── FORK: the money loop through the page's own server (TB_RPC_TEST = a local fork). Step 1 QA.forkWallet(user) makes the fly wallet;
 * step 2, in node, `FORK_RPC=… node banc-fly-qa-20261108.mjs --fund <fly address>` funds it ON THE FORK; step 3 QA.runFork(). ── */
async function forkWallet(user) { const s = await freshWallet({ running: false, owner: String(user).toLowerCase() }); return s.address; }
const waitNote = async (re, ms = 120000) => { for (let t = 0; t < ms; t += 500) { if (notes().some((x) => re.test(x))) return true; await sleep(500); } return false; };
async function runFork() {
  results.length = 0; unstub();
  const sym = T().current().symbol, stock = T().current().address;
  const acct = () => T().autoAccount(stock);
  const a0 = await acct();
  if (!check('fork wallet funded', BigInt(a0.usdc) >= 2000000n && BigInt(a0.eth) > 0n, 'USDC ' + a0.usdc + ', ETH ' + a0.eth + ', block ' + a0.block)) return results;
  $('autoProven').checked = false; $('autoCap').value = '2'; $('autoDay').value = '10';
  T().auto.s.running = true; localStorage.setItem('fly-auto-wallet-v1', JSON.stringify(T().auto.s)); window.dispatchEvent(new StorageEvent('storage', { key: 'fly-auto-wallet-v1' }));

  /* F0 no record: its edge does not pay the fee, no buy on the fork either */
  T().session.restore({ ...T().session.state(), tally: { consistent: 0, opposite: 0, flat: 0, undecided: 0 }, typical: 0.0015 });
  await T().autoTrade(decision('approach'));
  const a00 = await acct();
  check('no record: no buy on the fork, balances unchanged', /does not pay the fee yet: .* no buy/.test(notes()[0]) && a00.usdc === a0.usdc && BigInt(a00.stock) === 0n, notes()[0].slice(0, 200));
  /* F1 BUY, real, with an earned record whose edge pays the fee (the 2 USDC cap), then its seal read back from the chain */
  await earned(); const kellyAmt = 2000000n; /* the amount bought: min(USDC, cap) */
  await T().autoTrade(decision('approach'));
  const a1 = await acct(), seal = JSON.parse(localStorage.getItem('fly-seal-v1-' + sym) || 'null');
  check('BUY ' + sym + ' on the fork, edge pays the fee (' + kellyAmt + ' units, fee read ' + T().session.feePips + ')', notes().some((x) => /BUY .* done on its own \(1\/10/.test(x)) && BigInt(a1.stock) > 0n && BigInt(a0.usdc) - BigInt(a1.usdc) === kellyAmt,
    'stock ' + a1.stock + ', USDC ' + a0.usdc + ' -> ' + a1.usdc + ' · ' + notes().slice(0, 3).join(' | ').slice(0, 200));
  let sealGas = null;
  if (seal) { const q = await fetch('/api/fly/receipt/' + seal.tx + '?tx=1').then((x) => x.json()); sealGas = q.receipt ? Number(BigInt(q.receipt.gasUsed)) : null; }
  for (let k = 0; k < 20 && !/Read from the chain|Not confirmed/.test($('sealState').textContent); k++) await sleep(500);
  check('the trade is sealed by the fly itself and read back from the chain', seal && /Read from the chain/.test($('sealState').textContent),
    (seal ? 'seal tx ' + seal.tx.slice(0, 12) + ', gas used ' + sealGas + ' · ' : 'no seal · ') + $('sealState').textContent.slice(0, 140));

  /* F2 HOLD while it holds */
  await T().autoTrade(decision('approach'));
  check('HOLD while holding sends nothing', /HOLD .* no trade/.test(notes()[0]), notes()[0].slice(0, 140));

  /* F3 the daily cap holds (1 trade today, cap 1) */
  $('autoDay').value = '1'; await T().autoTrade(decision('avoid'));
  check('daily cap holds a SELL back once reached', /cap of 1 trades is reached/.test(notes()[0]), notes()[0].slice(0, 140)); $('autoDay').value = '10';

  /* F4 Stop pressed while a SELL is in flight (record gate ON: a SELL is not held back by it) */
  $('autoProven').checked = true;
  { let stopped = false; const real = window.__realFetch || window.fetch.bind(window); window.__realFetch = real;
    window.fetch = async (u, i) => { if (!stopped && String(u).includes('/api/fly/relay')) { stopped = true; T().autoStop(); } return real(u, i); };
    await T().autoTrade(decision('avoid')); unstub();
    const a = await acct();
    check('Stop during a SELL: the call in flight finishes, nothing more goes out', stopped && BigInt(a.stock) > 0n && !JSON.parse(localStorage.getItem('fly-auto-wallet-v1')).running && notes().some((x) => /stopped before sending|stopped/.test(x)),
      'stock still ' + a.stock + ' · ' + notes().slice(0, 3).join(' | ').slice(0, 220)); }

  /* F5 SELL, real, gate ON and record at 0: allowed */
  T().autoStart(); await T().autoTrade(decision('avoid'));
  const a5 = await acct();
  check('SELL ' + sym + ' on the fork with the record gate on', BigInt(a5.stock) === 0n && BigInt(a5.usdc) > BigInt(a1.usdc) && notes().some((x) => /SELL .* done on its own/.test(x)),
    'stock ' + a5.stock + ', USDC ' + a1.usdc + ' -> ' + a5.usdc + ' (round trip cost ' + (BigInt(a0.usdc) - BigInt(a5.usdc)) + ' units of ' + kellyAmt + ')');

  /* F6 the planner busy (NON_MESURE): no order, the fly keeps running */
  stubFetch([[/\/api\/rails\/plan/, () => ({ ok: false, etat: 'NON_MESURE', pourquoi: 'planner busy (stub)' })]]);
  $('autoProven').checked = false; await T().autoTrade(decision('approach')); unstub();
  check('planner NON_MESURE: no order, still running', /no order \(NON_MESURE/.test(notes()[0]) && JSON.parse(localStorage.getItem('fly-auto-wallet-v1')).running, notes()[0].slice(0, 140));

  /* F7 out of gas: balances read as almost no ETH -> it stops before signing */
  stubFetch([[/\/api\/fly\/account\//, async (u) => ({ ...(await (await window.__realFetch(u)).json()), eth: '1000' })]]);
  await T().autoTrade(decision('approach')); unstub();
  check('out of ETH for gas: the fly stops, nothing signed', /out of ETH for gas/.test(notes()[0]) && !JSON.parse(localStorage.getItem('fly-auto-wallet-v1')).running, notes()[0].slice(0, 140));

  /* F8 Withdraw all, real: everything back to the wallet that funded it */
  window.confirm = () => true; await T().autoWithdraw();
  const a8 = await acct();
  check('Withdraw all on the fork', BigInt(a8.usdc) === 0n && BigInt(a8.stock) === 0n && BigInt(a8.eth) < 10000000000000n && notes().some((x) => /^(\d{4}-\d\d-\d\d )?[\d:]{8} · withdrawn/.test(x)),
    'left: USDC ' + a8.usdc + ', stock ' + a8.stock + ', ETH ' + a8.eth + ' wei · ' + notes().slice(0, 3).join(' | ').slice(0, 200));
  const ko = results.filter((r) => !r.ok).length; console.log(results.length + ' fork scenarios, ' + ko + ' KO');
  return { n: results.length, ko, results };
}

return { runLogic, runFork, forkWallet, notes, stubFetch, unstub, moneyStubs, freshWallet, decision, results };
})();
